.darma-loader-darma-b8-neon-pulse-ring { --accent: var(--loader-color, #22d3ee); --accent-2: var(--loader-secondary-color, #e879f9); width: var(--loader-size, 72px); height: var(--loader-size, 72px); border-radius: 50%; border: calc(var(--loader-size, 72px) * .05) solid var(--accent); position: relative; animation: darma-loader-darma-b8-neon-pulse-ring-neon calc(var(--loader-speed, 1s) * 1.6) ease-in-out infinite; }
.darma-loader-darma-b8-neon-pulse-ring::before { content: ''; position: absolute; inset: 18%; border-radius: 50%; border: calc(var(--loader-size, 72px) * .03) solid var(--accent-2); box-shadow: 0 0 calc(var(--loader-size, 72px) * .1) var(--accent-2), inset 0 0 calc(var(--loader-size, 72px) * .06) var(--accent-2); }
@keyframes darma-loader-darma-b8-neon-pulse-ring-neon { 0%, 100% { box-shadow: 0 0 calc(var(--loader-size, 72px) * .08) var(--accent), inset 0 0 calc(var(--loader-size, 72px) * .08) var(--accent); opacity: .7; } 50% { box-shadow: 0 0 calc(var(--loader-size, 72px) * .3) var(--accent), inset 0 0 calc(var(--loader-size, 72px) * .2) var(--accent); opacity: 1; } }

